using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes the chat title. Supported only for basic groups, supergroups and channels. Requires can_change_info member right
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetChatTitleAsync(long chatId = default, string title = default)
    {

           using var activity =  StartCallActivity("SetChatTitleAsync", typeof(SetChatTitle).FullName ?? "SetChatTitleAsync");

           try
           {
             return client.SetChatTitleAsync(chatId, title);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
